    await ui.refresh(pg_wes);
    expect(await ui.delegate(pg_wes, {"user": "uma", "from": "2026-03-05", "to": "2026-04-02"})).toBe(true);
    await ui.refresh(pg_uma);
    expect(await ui.holdClaim(pg_uma, c_dot_0)).toBe(true);
