import java.sql.Date;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Function;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimNumbering;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/**
 * Copies a sheet to another, never used, id. The copy takes the sheet's today, settings, roles, rates, holidays, void
 * reasons, templates, people (with their grades, terms, contacts, aliases, holds, retirements and patrons), pools,
 * periods (all open, no figures fixed) and claims (status, frozen due, dates, notes and their logs, unbound from any
 * statement). Statements, watches, delegations, settle batches and archiving are not copied. The copy's claims are
 * numbered afresh by its own numbering, in the order the originals were opened: by the sheet's today when each was
 * opened, then by the order they were copied in (people in list order, each one's claims as added).
 */
@Repository
public class CloneRepository {

    /** The tables kept per sheet: a sheet with a row in any of them (or one loaded) has been used. */
    private static final List<String> SHEET_TABLES = List.of("person", "claim", "rate", "setting", "user_role", "period",
            "pool", "holiday", "void_reason", "claim_template", "delegation", "statement", "sheet_archived", "watch");

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;
    private final ClaimRepository claims;
    private final PeriodRepository periods;
    private final SettingRepository settings;

    public CloneRepository(JdbcTemplate jdbc, SheetRepository sheets, ClaimRepository claims, PeriodRepository periods,
            SettingRepository settings) {
        this.jdbc = jdbc;
        this.sheets = sheets;
        this.claims = claims;
        this.periods = periods;
        this.settings = settings;
    }

    /** Whether the sheet has never been used: never loaded, never changed, nothing kept for it. */
    public boolean unused(String id) {
        if (sheets.exists(id)) {
            return false;
        }
        for (String table : SHEET_TABLES) {
            Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM " + table + " WHERE sheet_id = ?", Integer.class, id);
            if (n != null && n > 0) {
                return false;
            }
        }
        return true;
    }

    /** Copies sheet {@code from} to the unused sheet {@code to} (see the class comment); from then on {@code to} exists. */
    public void copy(String from, String to) {
        sheets.saveToday(to, sheets.today(from));
        sheets.markLoaded(to);
        for (String table : List.of("setting", "setting_log", "user_role", "user_role_log", "rate", "rate_log", "rate_version", "holiday", "void_reason",
                "claim_template")) {
            copy(table, "WHERE sheet_id = ?" + (hasColumn(table, "id") ? " ORDER BY id" : ""), from, to, Map.of());
        }

        Map<Object, Object> people = copy("person", "WHERE sheet_id = ? ORDER BY id", from, to, Map.of());
        Map<String, Function<Map<String, Object>, Object>> ofPerson = Map.of("person_id", (r) -> people.get(r.get("person_id")));
        for (String table : List.of("person_grade", "person_grade_log", "person_terms_log", "person_terms_from", "person_alias", "person_hold",
                "person_retire_log", "person_retirement")) {
            copy(table, "WHERE sheet_id = ? ORDER BY " + (hasColumn(table, "id") ? "id" : "person_id"), from, to, ofPerson);
        }
        copy("patron", "WHERE sheet_id = ? ORDER BY named_seq", from, to, Map.of(
                "person_id", (r) -> people.get(r.get("person_id")),
                "patron_id", (r) -> people.get(r.get("patron_id"))));

        Map<Object, Object> pools = copy("pool", "WHERE sheet_id = ? ORDER BY id", from, to, Map.of());
        Map<String, Function<Map<String, Object>, Object>> member = new HashMap<>();
        member.put("pool_id", (r) -> pools.get(r.get("pool_id")));
        member.put("person_id", (r) -> r.get("person_id") == null ? null : people.get(r.get("person_id")));
        member.put("member_pool_id", (r) -> r.get("member_pool_id") == null ? null : pools.get(r.get("member_pool_id")));
        copy("pool_member", "WHERE pool_id IN (SELECT id FROM pool WHERE sheet_id = ?) ORDER BY id", from, null, member);

        Map<Object, Object> crews = copy("crew", "WHERE sheet_id = ? ORDER BY id", from, to,
                Map.of("lead_id", (r) -> people.get(r.get("lead_id"))));
        copy("crew_member", "WHERE crew_id IN (SELECT id FROM crew WHERE sheet_id = ?) ORDER BY id", from, null,
                Map.of("crew_id", (r) -> crews.get(r.get("crew_id")), "person_id", (r) -> people.get(r.get("person_id"))));

        Map<String, Function<Map<String, Object>, Object>> open = new HashMap<>();
        open.put("closed", (r) -> false);
        open.put("soft_closed", (r) -> false);
        open.put("closed_total", (r) -> null);
        open.put("locked", (r) -> false);
        copy("period", "WHERE sheet_id = ? ORDER BY id", from, to, open);

        Map<String, Function<Map<String, Object>, Object>> claim = new HashMap<>();
        claim.put("person_id", (r) -> people.get(r.get("person_id")));
        claim.put("claim_number", (r) -> null);
        claim.put("stated", (r) -> false);
        claim.put("stated_due", (r) -> null);
        claim.put("locked_by", (r) -> null);
        Map<Object, Object> copied = copy("claim", "c WHERE c.sheet_id = ? ORDER BY "
                + "(SELECT p.position FROM person p WHERE p.id = c.person_id), c.person_id, c.id", from, to, claim);
        Map<String, Function<Map<String, Object>, Object>> ofClaim = Map.of("claim_id", (r) -> copied.get(r.get("claim_id")));
        for (String table : List.of("claim_log", "claim_edit", "claim_comment", "claim_line", "claim_reminder")) {
            copy(table, "WHERE sheet_id = ? ORDER BY id", from, to, ofClaim);
        }
        copy("claim_void_reason", "WHERE sheet_id = ?", from, to, ofClaim);
        copy("claim_proof_log", "WHERE claim_id IN (SELECT id FROM claim WHERE sheet_id = ?) ORDER BY id", from, null, ofClaim);
        copy("claim_defer_log", "WHERE claim_id IN (SELECT id FROM claim WHERE sheet_id = ?) ORDER BY id", from, null, ofClaim);

        renumber(from, to, copied);
    }

    /** Gives the copied claims that had a number one afresh, by the copy's own numbering, in the order the originals
     *  were opened; a correction or split names the claim it corrects or was split from by its new number. */
    private void renumber(String from, String to, Map<Object, Object> copied) {
        record Numbered(long id, long copy, String number, LocalDate opened) {
        }
        List<Numbered> numbered = new ArrayList<>();
        jdbc.query("SELECT c.id, c.claim_number, c.claim_date, (SELECT MIN(l.log_date) FROM claim_log l WHERE l.sheet_id = c.sheet_id "
                + "AND l.claim_id = c.id AND l.status = 'OPEN') AS opened FROM claim c WHERE c.sheet_id = ? AND c.claim_number IS NOT NULL",
                (rs) -> {
                    LocalDate opened = rs.getObject("opened", LocalDate.class);
                    long id = rs.getLong("id");
                    numbered.add(new Numbered(id, ((Number) copied.get(id)).longValue(), rs.getString("claim_number"),
                            opened == null ? rs.getObject("claim_date", LocalDate.class) : opened));
                }, from);
        numbered.sort(Comparator.comparing(Numbered::opened).thenComparingLong(Numbered::copy));
        Map<String, String> renumbered = new HashMap<>();
        for (Numbered n : numbered) {
            Claim claim = claims.find(to, n.copy());
            String number = ClaimNumbering.next(claim, claims, periods, settings, sheets);
            claims.renumber(claim, number);
            renumbered.put(n.number(), number);
        }
        for (String column : List.of("corrects", "split_from")) {
            jdbc.query("SELECT id, " + column + " FROM claim WHERE sheet_id = ? AND " + column + " IS NOT NULL", (rs) -> {
                String was = rs.getString(2);
                if (renumbered.containsKey(was)) {
                    jdbc.update("UPDATE claim SET " + column + " = ? WHERE id = ?", renumbered.get(was), rs.getLong(1));
                }
            }, to);
        }
    }

    /**
     * Copies the rows of {@code table} picked by {@code where} (its one parameter: the sheet copied from) in that order,
     * each with every stored column as it was but its own id (given afresh), its sheet ({@code to}, when not null) and
     * the columns {@code overrides} works out from the row. Returns the new id of each row by its old id (tables with an
     * id of their own).
     */
    private Map<Object, Object> copy(String table, String where, String from, String to,
            Map<String, Function<Map<String, Object>, Object>> overrides) {
        List<String> columns = jdbc.queryForList("SELECT LOWER(COLUMN_NAME) FROM INFORMATION_SCHEMA.COLUMNS "
                + "WHERE TABLE_SCHEMA = 'PUBLIC' AND TABLE_NAME = ? AND IS_GENERATED = 'NEVER' AND IS_IDENTITY = 'NO' "
                + "ORDER BY ORDINAL_POSITION", String.class, table.toUpperCase(Locale.ROOT));
        boolean ownId = hasColumn(table, "id") && !columns.contains("id");
        String insert = "INSERT INTO " + table + " (" + String.join(", ", columns) + ") VALUES ("
                + String.join(", ", columns.stream().map((c) -> "?").toList()) + ")";
        Map<Object, Object> ids = new HashMap<>();
        for (Map<String, Object> row : jdbc.queryForList("SELECT * FROM " + table + " " + where, from)) {
            Object[] values = new Object[columns.size()];
            for (int i = 0; i < values.length; i++) {
                String column = columns.get(i);
                Function<Map<String, Object>, Object> override = overrides.get(column);
                values[i] = override != null ? override.apply(row)
                        : column.equals("sheet_id") && to != null ? to
                        : row.get(column);
                if (values[i] instanceof LocalDate date) {
                    values[i] = Date.valueOf(date);
                }
            }
            if (!ownId) {
                jdbc.update(insert, values);
                continue;
            }
            GeneratedKeyHolder keys = new GeneratedKeyHolder();
            jdbc.update(con -> {
                PreparedStatement ps = con.prepareStatement(insert, new String[] { "id" });
                for (int i = 0; i < values.length; i++) {
                    ps.setObject(i + 1, values[i]);
                }
                return ps;
            }, keys);
            ids.put(row.get("id"), keys.getKey().longValue());
        }
        return ids;
    }

    private boolean hasColumn(String table, String column) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = 'PUBLIC' "
                + "AND TABLE_NAME = ? AND COLUMN_NAME = ?", Integer.class, table.toUpperCase(Locale.ROOT),
                column.toUpperCase(Locale.ROOT));
        return n != null && n > 0;
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Clones the sheet to another id (see CloneRepository). Only a steward may clone, and only to an id never used. */
public class CloneSheet {
    public void cloneSheet(@PathVariable("sheetId") String sheetId, @Val CloneRequest request, CloneRepository clones,
            RoleRepository roles, Out<SheetClone> clone) throws InvalidCloneException {
        String id = sheetId.trim();
        if (!RoleRepository.STEWARD.equals(roles.roleOf(id, request.by()))) {
            throw new InvalidCloneException("Only a steward may clone the sheet");
        }
        if (request.to().isEmpty() || request.to().contains("/") || request.to().equals(id)
                || !clones.unused(request.to())) {
            throw new InvalidCloneException("The sheet can only be cloned to an id never used");
        }
        clones.copy(id, request.to());
        clone.set(new SheetClone(id, request.to()));
    }
}
package net.officefloor.hq.app.rate;

import java.sql.Date;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored rates, one per grade and from-date per sheet: the newest version, the one in force, with the older versions
 *  it replaced kept in rate_version. A grade with no row has no rate. */
@Repository
public class RateRepository {

    private static final String COLUMNS = "sheet_id, grade, rate, from_date, to_date, after_seq";
    private static final String VERSIONED = COLUMNS + ", version";

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;
    private final SettingRepository settings;

    public RateRepository(JdbcTemplate jdbc, SheetRepository sheets, SettingRepository settings) {
        this.jdbc = jdbc;
        this.sheets = sheets;
        this.settings = settings;
    }

    /** The sheets whose rates the sheet uses, in the order looked at: itself, then its parent, the parent's parent,
     *  up to SettingRepository#PARENT_LEVELS levels up. */
    public List<String> chain(String sheetId) {
        List<String> chain = new ArrayList<>();
        chain.add(sheetId);
        chain.addAll(settings.ancestors(sheetId, SettingRepository.PARENT_LEVELS));
        return chain;
    }

    /** As chain, as of a date: the parent the sheet had then (see SettingRepository#parentAsOf), none when it had
     *  none, then that parent's ancestors as they are now. */
    public List<String> chainAsOf(String sheetId, LocalDate asOf) {
        List<String> chain = new ArrayList<>();
        chain.add(sheetId);
        String parent = settings.parentAsOf(sheetId, asOf);
        if (parent != null && !parent.equals(sheetId)) {
            chain.add(parent);
            for (String up : settings.ancestors(parent, SettingRepository.PARENT_LEVELS - 1)) {
                if (up.equals(sheetId) || chain.contains(up)) {
                    break;
                }
                chain.add(up);
            }
        }
        return chain;
    }

    /** The sheet's rates, by grade, then from-date (one with none first). */
    public List<Rate> list(String sheetId) {
        return jdbc.query("SELECT " + VERSIONED + " FROM rate WHERE sheet_id = ? ORDER BY grade, from_date NULLS FIRST",
                RateRepository::map, sheetId);
    }

    /** The grade's rate in force on a date on the sheet (see own), or, when it has none, the one in force on its
     *  parent, then the parent's parent, up to three levels up; null when none of them has one. */
    public Rate find(String sheetId, String grade, LocalDate on) {
        for (String sheet : chain(sheetId)) {
            Rate rate = own(sheet, grade, on);
            if (rate != null) {
                return rate;
            }
        }
        return null;
    }

    /** The grade's rate in force on a date — the latest from-date on or before it, a rate with none applying
     *  from the beginning of time — or null when no rate applies, or that rate's to-date is before the date. */
    public Rate own(String sheetId, String grade, LocalDate on) {
        List<Rate> found = jdbc.query("SELECT " + VERSIONED + " FROM rate WHERE sheet_id = ? AND grade = ?"
                + " AND (from_date IS NULL OR from_date <= ?) ORDER BY from_date DESC NULLS LAST LIMIT 1",
                RateRepository::map, sheetId, grade, Date.valueOf(on));
        if (found.isEmpty() || (found.get(0).to() != null && found.get(0).to().isBefore(on))) {
            return null;
        }
        return found.get(0);
    }

    /** The grade's rate that applies to a claim — dated {@code on}, added with the added sequence {@code seq} (null: one
     *  not yet added) — on the sheet (see ownFor), or, when it has none, on its parent, then the parent's parent, up to
     *  three levels up; null when none of them has one. Unlike find, a forward-only rate saved after the claim was added
     *  is passed over (see Rate#appliesTo). */
    public Rate forClaim(String sheetId, String grade, LocalDate on, Long seq) {
        for (String sheet : chain(sheetId)) {
            Rate rate = ownFor(sheet, grade, on, seq);
            if (rate != null) {
                return rate;
            }
        }
        return null;
    }

    /** The grade's rate on the sheet that applies to a claim dated {@code on} added with the added sequence {@code seq}:
     *  see #pick, over every version of the grade's rates. */
    public Rate ownFor(String sheetId, String grade, LocalDate on, Long seq) {
        List<Rate> all = new ArrayList<>(jdbc.query("SELECT " + VERSIONED + " FROM rate WHERE sheet_id = ? AND grade = ?"
                + " AND (from_date IS NULL OR from_date <= ?)", RateRepository::map, sheetId, grade, Date.valueOf(on)));
        if (all.stream().anyMatch((r) -> r.after() != null) || hasForward(sheetId, grade)) {
            all.addAll(jdbc.query("SELECT " + VERSIONED + " FROM rate_version WHERE sheet_id = ? AND grade = ?"
                    + " AND (from_date IS NULL OR from_date <= ?)", RateRepository::map, sheetId, grade, Date.valueOf(on)));
        }
        return pick(all, grade, on, seq);
    }

    private boolean hasForward(String sheetId, String grade) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM rate_version WHERE sheet_id = ? AND grade = ?"
                + " AND after_seq IS NOT NULL", Integer.class, sheetId, grade);
        return n != null && n > 0;
    }

    /** Of the versions given (of one sheet's rates), the grade's rate that applies to a claim dated {@code on} added
     *  with the added sequence {@code seq} (null: one not yet added): for each from-date, the newest version that
     *  applies to the claim (see Rate#appliesTo), then of those the one with the latest from-date on or before the
     *  date, one with none applying from the beginning of time; null when none applies, or that rate's to-date is
     *  before the date. */
    public static Rate pick(List<Rate> versions, String grade, LocalDate on, Long seq) {
        Rate found = null;
        for (Rate r : versions) {
            if (!r.grade().equals(grade) || (r.from() != null && r.from().isAfter(on)) || !r.appliesTo(seq)) {
                continue;
            }
            int byFrom = found == null ? 1
                    : r.from() == null ? (found.from() == null ? 0 : -1)
                    : found.from() == null ? 1 : r.from().compareTo(found.from());
            if (byFrom > 0 || (byFrom == 0 && r.version() > found.version())) {
                found = r;
            }
        }
        return found == null || (found.to() != null && found.to().isBefore(on)) ? null : found;
    }

    /** The older versions of the grade's rate for a from-date on the sheet, newest first. */
    public List<Rate> older(String sheetId, String grade, LocalDate from) {
        return jdbc.query("SELECT " + VERSIONED + " FROM rate_version WHERE sheet_id = ? AND grade = ?"
                + " AND from_date IS NOT DISTINCT FROM ? ORDER BY version DESC", RateRepository::map, sheetId, grade,
                from == null ? null : Date.valueOf(from));
    }

    /** The added sequence of a claim (see Rate#appliesTo); null when there is no such claim. */
    public Long seqOf(long claimId) {
        List<Long> found = jdbc.queryForList("SELECT added_seq FROM claim WHERE id = ?", Long.class, claimId);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Every rate stored on the sheet while its today was on or before the date, in the order stored. */
    public List<Rate> storedBy(String sheetId, LocalDate madeOn) {
        return jdbc.query("SELECT " + COLUMNS + " FROM rate_log WHERE sheet_id = ? AND made_on <= ? ORDER BY id",
                RateRepository::logged, sheetId, Date.valueOf(madeOn));
    }

    /** Stores the rate as the newest version of the grade's rate for its from-date: the one it had for that from-date
     *  is kept as an older version, the new one numbered after it (1 when it had none). One with a from-date on or after
     *  the sheet's today is forward-only: it applies only to claims added after now (see Rate#after). Logs it with the
     *  sheet's today. */
    public Rate save(Rate set) {
        LocalDate today = sheets.today(set.sheetId());
        if (set.from() != null && !set.from().isBefore(today)) {
            set = set.withAfter(jdbc.queryForObject("SELECT COALESCE(MAX(added_seq), 0) FROM claim", Long.class));
        }
        Date from = set.from() == null ? null : Date.valueOf(set.from());
        String same = " WHERE sheet_id = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?";
        jdbc.update("INSERT INTO rate_version (" + VERSIONED + ") SELECT " + VERSIONED + " FROM rate" + same,
                set.sheetId(), set.grade(), from);
        Integer last = jdbc.queryForObject("SELECT MAX(version) FROM rate" + same, Integer.class,
                set.sheetId(), set.grade(), from);
        Rate rate = set.withVersion(last == null ? 1 : last + 1);
        jdbc.update("DELETE FROM rate" + same, rate.sheetId(), rate.grade(), from);
        jdbc.update("INSERT INTO rate (" + VERSIONED + ") VALUES (?, ?, ?, ?, ?, ?, ?)",
                rate.sheetId(), rate.grade(), rate.rate(), from, rate.to() == null ? null : Date.valueOf(rate.to()),
                rate.after(), rate.version());
        jdbc.update("INSERT INTO rate_log (" + COLUMNS + ", made_on) VALUES (?, ?, ?, ?, ?, ?, ?)",
                rate.sheetId(), rate.grade(), rate.rate(), from, rate.to() == null ? null : Date.valueOf(rate.to()),
                rate.after(), Date.valueOf(today));
        return rate;
    }

    private static Rate map(ResultSet rs, int n) throws SQLException {
        return logged(rs, n).withVersion(rs.getInt("version"));
    }

    /** A rate as logged, which keeps no version (see SheetAsOf for how it counts them). */
    private static Rate logged(ResultSet rs, int n) throws SQLException {
        Date from = rs.getDate("from_date");
        Date to = rs.getDate("to_date");
        long after = rs.getLong("after_seq");
        return new Rate(rs.getString("sheet_id"), rs.getString("grade"), rs.getBigDecimal("rate").setScale(2),
                from == null ? null : from.toLocalDate(), to == null ? null : to.toLocalDate())
                .withAfter(rs.wasNull() ? null : after);
    }
}

